import sys, math

def main():
    data = sys.stdin.buffer.read().split(b'\n')
    groups = {}
    for line in data[1:]:
        if not line:
            continue
        parts = line.split(b',')
        if len(parts) < 3:
            continue
        cat = parts[1].rstrip(b'\r')
        try:
            v = float(parts[2])
        except ValueError:
            continue
        g = groups.get(cat)
        if g is None:
            groups[cat] = [v]
        else:
            g.append(v)
    out = []
    for cat in sorted(groups):
        out.append(cat.decode() + ',' + ('%.2f' % math.fsum(groups[cat])))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

main()
